#include "tigersheets/ooxml.hpp"
#include <pugixml.hpp>
#include <zip.h>
#include <filesystem>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <unistd.h>
using namespace tigersheets;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void replaceMember(const std::string& path,const std::string& text){int error=0;auto* archive=zip_open(path.c_str(),0,&error);require(archive,"open native fixture");auto* source=zip_source_buffer(archive,text.data(),text.size(),0);require(source&&zip_file_add(archive,"xl/worksheets/sheet1.xml",source,ZIP_FL_OVERWRITE)>=0&&zip_close(archive)==0,"write native ignored errors fixture");}
Json range(int r1,int c1,int r2,int c2){return {{"row1",r1},{"col1",c1},{"row2",r2},{"col2",c2}};}
}
int main(){const auto directory=std::filesystem::temp_directory_path()/("tigersheets-ignored-errors-"+std::to_string(getpid()));std::filesystem::create_directories(directory);try{
 const auto path=(directory/"source.xlsx").string();auto book=WorkbookSession().snapshot();book["sheets"][0]["cells"]=Json::array({{{"row",4},{"col",3},{"input","123"}},{{"row",9},{"col",5},{"input","=C4"}}});writeWorkbook(path,book);auto original=readWorkbook(path);pugi::xml_document doc;require(doc.load_string(original.entries.at("xl/worksheets/sheet1.xml").c_str()),"fixture XML");auto root=doc.document_element();auto errors=root.append_child("ignoredErrors");auto rule=errors.append_child("ignoredError");rule.append_attribute("sqref")="C3:E7 A10 B2";rule.append_attribute("numberStoredAsText")=1;rule.append_attribute("formula")=0;auto other=errors.append_child("ignoredError");other.append_attribute("sqref")="F4:F5";other.append_attribute("formulaRange")=1;std::ostringstream xml;doc.save(xml);replaceMember(path,xml.str());auto source=readWorkbook(path);const auto id=source.workbook.at("sheets")[0].at("id").get<std::string>();
 const auto expected=Json::array({{{"ranges",Json::array({range(3,3,7,5),range(10,1,10,1),range(2,2,2,2)})},{"checks",{{"numberStoredAsText",true},{"formula",false}}}},{{"ranges",Json::array({range(4,6,5,6)})},{"checks",{{"formulaRange",true}}}}});
 require(source.workbook.at("sheets")[0].value("ignoredErrors",Json::array())==expected,"native ignoredErrors import retains every disjoint range and true/false check");preflightWorksheetStructure(source,id);WorkbookSession session(source.workbook);const auto baseline=session.snapshot();require(session.apply(0,Json::array({{{"type","insert_rows"},{"sheet",id},{"index",4},{"count",2}}})),"insert rows through native structural transaction");auto inserted=session.snapshot();auto shifted=expected;shifted[0]["ranges"][0]=range(3,3,9,5);shifted[0]["ranges"][1]=range(12,1,12,1);shifted[1]["ranges"][0]=range(6,6,7,6);require(inserted.at("sheets")[0].at("ignoredErrors")==shifted,"inserting within an ignored range expands it and shifts independent ranges");require(session.undo()&&session.snapshotView().at("sheets")==baseline.at("sheets"),"ignored ranges and cells restore in one Undo");require(session.redo(),"ignored ranges support redo");
 require(session.apply(session.snapshotView().at("revision"),Json::array({{{"type","delete_rows"},{"sheet",id},{"index",6},{"count",2}},{{"type","delete_columns"},{"sheet",id},{"index",4},{"count",2}}})),"delete partial and complete ignored ranges");const auto edited=session.snapshot();const auto retained=Json::array({{{"ranges",Json::array({range(3,3,7,3),range(10,1,10,1),range(2,2,2,2)})},{"checks",{{"numberStoredAsText",true},{"formula",false}}}}});require(edited.at("sheets")[0].at("ignoredErrors")==retained,"deletion contracts partial ranges and removes an empty rule");const auto saved=(directory/"saved.xlsx").string();writeWorkbook(saved,edited,&source);auto reopened=readWorkbook(saved);require(reopened.workbook.at("sheets")[0].at("ignoredErrors")==retained,"changed ignored checks roundtrip through native XML");pugi::xml_document result;require(result.load_string(reopened.entries.at("xl/worksheets/sheet1.xml").c_str()),"saved XML");auto native=result.document_element().child("ignoredErrors").child("ignoredError");require(std::string(native.attribute("sqref").value())=="C3:C7 A10 B2"&&native.attribute("numberStoredAsText").as_bool()&&!native.attribute("formula").as_bool()&&!native.next_sibling(),"native saved sqref and flags reflect final coordinates without stale rules");
 auto opaque=reopened;auto& bytes=opaque.entries["xl/worksheets/sheet1.xml"];bytes.insert(bytes.find("</ignoredErrors>"),"<extLst/>");bool blocked=false;try{preflightWorksheetStructure(opaque,id);}catch(const std::runtime_error&){blocked=true;}require(blocked,"unknown ignoredErrors extension remains protected before mutation");
 auto invalid=edited;invalid["sheets"][0]["ignoredErrors"][0]["ranges"][0]["row1"]=0;bool rejected=false;try{WorkbookSession test(invalid);}catch(const std::runtime_error&){rejected=true;}require(rejected,"invalid ignored range cannot enter a session");std::filesystem::remove_all(directory);std::cout<<"Native ignored-error structural references passed\n";
 }catch(const std::exception& error){std::filesystem::remove_all(directory);std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
